import fs from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import yaml from 'js-yaml';
import { encode } from '@toon-format/toon';
import { renderHelp } from '../toon.js';
import { getSuggestions } from '../suggestions.js';
const HOME_DIR = os.homedir();
const SKILL_ROOTS = [
    path.resolve(process.cwd(), 'skills'),
    path.resolve(HOME_DIR, '.agents', 'skills'),
    path.resolve(HOME_DIR, '.gemini', 'config', 'skills'),
];
function findSkills() {
    const skills = [];
    for (const root of SKILL_ROOTS) {
        if (!fs.existsSync(root))
            continue;
        let entries;
        try {
            entries = fs.readdirSync(root, { withFileTypes: true });
        }
        catch {
            continue;
        }
        for (const entry of entries) {
            if (!entry.isDirectory() && !entry.isSymbolicLink())
                continue;
            const skillYamlPath = path.join(root, entry.name, 'skill.yaml');
            if (!fs.existsSync(skillYamlPath))
                continue;
            try {
                const content = fs.readFileSync(skillYamlPath, 'utf8');
                const parsed = yaml.load(content);
                skills.push({
                    name: parsed.name || entry.name,
                    description: parsed.description || '',
                    initial_state: parsed.initial_state || 'START',
                    path: path.join(root, entry.name),
                });
            }
            catch {
                skills.push({
                    name: entry.name,
                    description: '',
                    initial_state: 'START',
                    path: path.join(root, entry.name),
                });
            }
        }
    }
    return skills
        .sort((a, b) => a.name.localeCompare(b.name))
        .reduce((acc, skill) => {
        if (!acc.find(s => s.name === skill.name)) {
            acc.push(skill);
        }
        return acc;
    }, []);
}
